 const dialogHelp={new:'draft','draft-review':'draft','generation-review':'draft',import:'import','import-review':'import',project:'brief',optimize:'improve','optimization-proposal':'comparison','optimization-comparison':'comparison','optimization-setup':'improve','record-test':'record','browser-migration':'migration','edit-resource':'supporting','add-reference':'references','edit-reference':'references','add-definition':'values','edit-definition':'values','review-steps':'batchReview',preview:'screens'}[mode];$('#dialog-title-help').innerHTML=dialogHelp?infoButton(dialogHelp):'';$('#dialog-title').textContent=title;$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=body+'<div id="dialog-error" class="dialog-error" role="alert" hidden></div>';$('#dialog-footer').innerHTML=(help?'<span class="small">'+help+'</span>':'')+extra+button(submit?'Cancel':'Close','close','','quiet')+(submit?`<button class="button primary" type="submit">${submit}</button>`:'');if(!$('#dialog').open)$('#dialog').showModal();if(mode==='run-review'){title='Run an independent AI review';body='<p>A fresh Claude Code session will compare the current skill with its original sources. It has no tools and cannot run imported code.</p><p>The instructions and original source contents in the review packet will be sent to Claude using your signed-in CLI account. Review may take a few minutes.</p><div id="review-engine-status" class="notice-box" role="status">Checking Claude Code…</div><p class="small">You will inspect the report before recording it. Findings and uncertain licensing can keep download blocked.</p>';submit='Start independent review';help='Cancel stops the request. No report is recorded automatically.';}
