function closeDialog(){contextHelp.close({restoreFocus:false});if(dialogState?.mode==='optimization-proposal'){pendingOptimization=null;pendingOptimizationProjectId='';}if(dialogState?.mode==='import'||dialogState?.mode==='import-review'){pendingImport=null;pendingImportProjectId='';importRequestToken++;}if($('#dialog').open)$('#dialog').close();dialogState=null;}
