function draftSetupNotes(skill,includeQuestions=true){const generation=skill.generation;return (generation.assumptions.length?'<div class="notice-box warning"><h3>Assumptions to review</h3><ul>'+generation.assumptions.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></div>':'')+(includeQuestions&&generation.questions.length?'<div class="notice-box warning"><h3>Open questions</h3><ul>'+generation.questions.map(question=>'<li>'+esc(question.text)+'</li>').join('')+'</ul></div>':'');}
async function checkDraftingEngine(){const current=dialogState;if(!(current?.mode==='new'&&newSkillMode==='prompt'||current?.mode==='optimize'))return;const target=$('#draft-engine-status');if(!/^https?:$/.test(location.protocol)){target.textContent='Start the local server to generate a skill with Claude Code. Start blank remains available in preview mode.';$('#dialog-form button[type="submit"]').disabled=true;return;}try{const response=await fetch('/api/skill-draft',{cache:'no-store'}),status=await response.json();if(dialogState!==current)return;target.textContent=status.ready?'Claude Code is ready · '+status.model+'. '+(current.mode==='optimize'?'The skill instructions, textual sources and goals are sent to Claude when you generate. Binary files use a manifest and existing guides.':'Your prompt is sent to Claude when you generate.'):status.message||'The drafting engine is unavailable.';$('#dialog-form button[type="submit"]').disabled=!status.ready;}catch{if(dialogState===current){target.textContent='The drafting service is unavailable. Restart the updated local server and try again.';$('#dialog-form button[type="submit"]').disabled=true;}}}
function optimizationNotes(skill,includeQuestions=true){const record=skill.optimization;return (record.assumptions.length?'<div class="notice-box warning"><h3>Assumptions to review</h3><ul>'+record.assumptions.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></div>':'')+(includeQuestions&&record.questions.length?'<div class="notice-box warning"><h3>Questions to resolve</h3><ul>'+record.questions.map(question=>'<li>'+esc(question.text)+'</li>').join('')+'</ul></div>':'');}
async function optimizationRequest(input,signal){const response=await fetch('/api/skill-optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input),signal}),result=await response.json();if(!response.ok)throw new Error(result.error||'Optimization failed.');return result;}
async function generateOptimizedVersion(goals,allowResequence){
 const destination=activeProjectId,sourceId=project.id,request=++draftToken;optimizationInput={goals,allowResequence};draftController=new AbortController();const controller=draftController,form=$('#dialog-form');form.querySelectorAll('input,textarea,button[type="submit"]').forEach(input=>input.disabled=true);$('#draft-progress').hidden=false;
 try{
  save();if(!(await persistence.flush())||persistence.hasChanges())throw new Error('Save the source skill and resolve any database conflict before optimizing.');
  const sourceDigest=await optimizationDigest(project),result=await optimizationRequest({projectId:destination,skillId:sourceId,sourceDigest,goals,allowResequence},controller.signal);if(request!==draftToken)return;
  const current=workspaceSkill(workspace,destination,sourceId);if(!current||await optimizationDigest(current)!==sourceDigest)throw new Error('The source skill changed during optimization. Generate a fresh proposal.');
  const next=readProject(JSON.stringify(result.skill));await verifyOptimizationEvidence(next);if(next.optimization?.sourceDigest!==sourceDigest)throw new Error('The proposal does not match the selected source.');
  pendingOptimization=next;pendingOptimizationProjectId=destination;draftController=null;openDialog('optimization-proposal');
 }catch(error){if(request!==draftToken)return;form.querySelectorAll('input,textarea,button[type="submit"]').forEach(input=>input.disabled=false);$('#draft-progress').hidden=true;dialogError(error.name==='AbortError'?'Optimization cancelled. No version was added.':error.message);}
 finally{if(draftController===controller)draftController=null;}
}
async function keepOptimizedVersion(){
 if(keepingOptimization)return;const next=pendingOptimization,destination=pendingOptimizationProjectId;if(!next)throw new Error('Create a proposed version first.');await verifyOptimizationEvidence(next);
 keepingOptimization=true;const currentDialog=dialogState,request=++draftToken,controller=new AbortController();draftController=controller;const submit=$('#dialog-form button[type="submit"]');submit.disabled=true;
 try{
  const record=next.optimization;save();if(!(await persistence.flush())||persistence.hasChanges())throw new Error('Resolve the database save conflict before keeping this version. The proposal remains open.');
  if(request!==draftToken||dialogState!==currentDialog)return;
  const source=workspaceSkill(workspace,destination,record.sourceId);if(!source||await optimizationDigest(source)!==record.sourceDigest)throw new Error('The source skill changed. Generate a fresh optimization before keeping a version.');
  await optimizationRequest({projectId:destination,skillId:record.sourceId,sourceDigest:record.sourceDigest,checkOnly:true},controller.signal);
  if(request!==draftToken||dialogState!==currentDialog)return;
  replaceProject(next,'',destination);pendingOptimization=null;pendingOptimizationProjectId='';draftController=null;closeDialog();
  const saved=await persistence.flush();notify(saved?'Improved version added. Review its decisions and steps, then test it.':'The proposed version is in this tab but could not be saved. Back up unsaved projects before reloading.',!saved);
 }catch(error){if(request===draftToken&&dialogState===currentDialog)throw error;}
 finally{keepingOptimization=false;if(draftController===controller)draftController=null;if(dialogState===currentDialog)submit.disabled=false;}
}
