const reviewReportInput=document.createElement('input');reviewReportInput.id='review-report-file';reviewReportInput.type='file';reviewReportInput.accept='.json';reviewReportInput.hidden=true;document.body.append(reviewReportInput);reviewReportInput.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Review reports must be at most 2 MB.');await acceptReviewReport(parseReviewerReport(await file.text()));}catch(error){notify(error.message,true);}});
async function acceptReviewReport(report){const base=project,snapshot=reviewSnapshot(project),target=copy(project);await recordIndependentReview(target,report);if(base!==project||snapshot!==reviewSnapshot(project))throw new Error('The skill changed while checking the report. Try again.');mutate(()=>{project.independentReview=target.independentReview;page='package';},'Independent review recorded. Read the findings before downloading.',{definitionChange:false});}
async function checkReviewEngine(){const current=dialogState,submit=$('#dialog-form button[type="submit"]');submit.disabled=true;try{const response=await fetch('/api/skill-draft',{cache:'no-store'}),status=await response.json();if(dialogState!==current)return;$('#review-engine-status').textContent=status.ready?'Claude Code is ready · '+status.model:status.message||'Claude Code is unavailable. Use another reviewer from the review panel.';submit.disabled=!status.ready;}catch{if(dialogState===current)$('#review-engine-status').textContent='Start the updated local server to use Claude Code. The external reviewer option remains available.';}}
async function runIndependentReview(){const current=dialogState,request=++reviewToken,controller=new AbortController();reviewController=controller;const submit=$('#dialog-form button[type="submit"]');submit.disabled=true;$('#review-engine-status').textContent='Reviewing in a fresh session… Cancel stops this request.';try{save();if(!await persistence.flush()||persistence.hasChanges())throw new Error('Resolve the database save conflict before review.');const base=project,snapshot=reviewSnapshot(project),sourceDigest=await reviewDigest(snapshot),sourceRevision=project.revision;const response=await fetch('/api/skill-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:activeProjectId,skillId:project.id,sourceDigest,sourceRevision}),signal:controller.signal}),result=await response.json();if(request!==reviewToken||dialogState!==current)return;if(!response.ok)throw new Error(result.error||'Independent review failed.');if(base!==project||snapshot!==reviewSnapshot(project)||result.sourceDigest!==sourceDigest||result.sourceRevision!==sourceRevision)throw new Error('The skill changed. Start a fresh review.');await recordIndependentReview(copy(project),result.report);pendingReview={report:result.report,snapshot};reviewController=null;openDialog('review-result');}catch(error){if(request===reviewToken&&dialogState===current){dialogError(error.name==='AbortError'?'Review cancelled. No report was recorded.':error.message);submit.disabled=false;}}finally{if(reviewController===controller)reviewController=null;}}
function createReviewSnapshotData(p){const value=copy(p);delete value.independentReview;return value;}
await initializeStorage();
window.addEventListener('beforeunload',event=>{if(persistence.hasChanges()){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)persistence.flush();});
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();showProjects();});
